// Generated by scripts/build-results-content.mjs — drawing and interaction code only, no survey data.

// ============================================================
// WTCharts — self-contained neon-dark SVG chart renderers.
// No external libraries, no CDN. Data lives in JS config objects;
// update numbers here, not images, when new survey data lands.
// ============================================================
window.WTCharts = (function () {
  const svgNS = "http://www.w3.org/2000/svg";
  const NAVY_TEXT = "#9fb3d9", WHITE_TEXT = "#F4F8FF";

  function el(tag, attrs, text) {
    const e = document.createElementNS(svgNS, tag);
    for (const k in attrs) e.setAttribute(k, attrs[k]);
    if (text !== undefined) e.textContent = text;
    return e;
  }

  function addDefs(svg) {
    const defs = el("defs", {});
    const shadow = el("filter", { id: "wt-shadow", x: "-80%", y: "-80%", width: "260%", height: "260%" });
    shadow.innerHTML = `<feDropShadow dx="0" dy="2" stdDeviation="3.5" flood-color="#000000" flood-opacity="0.5"/>`;
    defs.appendChild(shadow);
    const glow = el("filter", { id: "wt-glow", x: "-60%", y: "-60%", width: "220%", height: "220%" });
    glow.innerHTML = `<feGaussianBlur stdDeviation="3" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge>`;
    defs.appendChild(glow);
    svg.appendChild(defs);
    return defs;
  }

  function makeSvg(W, H) {
    const svg = el("svg", { viewBox: `0 0 ${W} ${H}`, width: "100%" });
    svg.style.display = "block";
    return svg;
  }

  // ---------------- Bubble scatter ----------------
  function bubble(hostEl, cfg) {
    const idp = cfg.idPrefix || Math.random().toString(36).slice(2, 8);
    const W = cfg.width || 760, H = cfg.height || 420;
    const M = { top: 44, right: 30, bottom: 46, left: cfg.marginLeft || 66 };
    const plotW = W - M.left - M.right, plotH = H - M.top - M.bottom;
    const xScale = x => M.left + (x / cfg.xMax) * plotW;
    const yScale = y => M.top + plotH - (y / cfg.yMax) * plotH;

    const svg = makeSvg(W, H);
    const defs = addDefs(svg);
    cfg.points.forEach((p, i) => {
      const g = el("radialGradient", { id: `wtgrad-${idp}-${i}`, cx: "35%", cy: "30%", r: "75%" });
      g.innerHTML = `<stop offset="0%" stop-color="${p.colorLight || '#fff'}" stop-opacity=".95"/>
        <stop offset="45%" stop-color="${p.color}" stop-opacity=".95"/>
        <stop offset="100%" stop-color="${p.color}" stop-opacity=".55"/>`;
      defs.appendChild(g);
    });

    const grid = el("g", {});
    (cfg.xTicks || []).forEach(t => {
      const x = xScale(t);
      grid.appendChild(el("line", { x1: x, x2: x, y1: M.top, y2: M.top + plotH, stroke: "rgba(255,255,255,.09)" }));
      grid.appendChild(el("text", { x, y: M.top + plotH + 20, fill: NAVY_TEXT, "font-size": 11, "text-anchor": "middle" }, String(t)));
    });
    (cfg.yTicks || []).forEach(t => {
      const y = yScale(t);
      grid.appendChild(el("line", { x1: M.left, x2: M.left + plotW, y1: y, y2: y, stroke: "rgba(255,255,255,.09)" }));
      grid.appendChild(el("text", { x: M.left - 10, y: y + 4, fill: NAVY_TEXT, "font-size": 11, "text-anchor": "end" },
        cfg.yFmt ? cfg.yFmt(t) : String(t)));
    });
    svg.appendChild(grid);

    svg.appendChild(el("text", { x: M.left + plotW / 2, y: H - 6, fill: NAVY_TEXT, "font-size": 12, "text-anchor": "middle" }, cfg.xLabel || ""));
    svg.appendChild(el("text", { x: M.left, y: M.top - 18, fill: NAVY_TEXT, "font-size": 12 }, cfg.yLabel || ""));

    if (cfg.curve) {
      const pts = [];
      for (let x = cfg.curve.xMin; x <= cfg.curve.xMax; x += cfg.curve.step) pts.push(`${xScale(x)},${yScale(cfg.curve.fn(x))}`);
      svg.appendChild(el("polyline", { points: pts.join(" "), fill: "none", stroke: "rgba(255,255,255,.4)", "stroke-width": 1.6, "stroke-dasharray": "6,5" }));
    }

    const rScale = pct => (cfg.rMin || 8) + Math.sqrt(pct) * (cfg.rFactor || 6.4);
    const order = cfg.points.map((p, i) => ({ p, i })).sort((a, b) => b.p.pct - a.p.pct);
    order.forEach(({ p, i }) => {
      const cx = xScale(p.x), cy = yScale(p.y), r = rScale(p.pct);
      svg.appendChild(el("circle", { cx, cy, r, fill: `url(#wtgrad-${idp}-${i})`, filter: "url(#wt-shadow)" }));
      const labelX = cx + (p.labelSide === 'left' ? -(r + 10) : (r + 10));
      const anchor = p.labelSide === 'left' ? 'end' : 'start';
      const dy = p.labelDy || 0;
      svg.appendChild(el("text", { x: labelX, y: cy - 4 + dy, fill: "#fff", "font-size": 13, "font-weight": 700, "text-anchor": anchor }, p.label));
      svg.appendChild(el("text", { x: labelX, y: cy + 12 + dy, fill: NAVY_TEXT, "font-size": 11, "text-anchor": anchor }, p.sub || ""));
    });
    hostEl.appendChild(svg);
  }

  // ---------------- Horizontal bar chart ----------------
  function wrapLabel(text, maxChars) {
    if (!maxChars) return [text];
    const words = String(text).split(" ");
    const lines = [];
    let cur = "";
    words.forEach(w => {
      const test = cur ? cur + " " + w : w;
      if (test.length > maxChars && cur) { lines.push(cur); cur = w; }
      else { cur = test; }
    });
    if (cur) lines.push(cur);
    return lines;
  }

  function hbar(hostEl, cfg) {
    const idp = cfg.idPrefix || Math.random().toString(36).slice(2, 8);
    const W = cfg.width || 760;
    const baseRowH = cfg.rowHeight || 54;
    const lineH = 15;
    const M = { top: 16, right: 70, bottom: 44, left: cfg.labelWidth || 150 };
    const plotW = W - M.left - M.right;
    const xScale = v => (v / cfg.xMax) * plotW;

    // Precompute wrapped label lines and per-row heights (rows can be taller
    // than baseRowH when a label wraps to multiple lines).
    const rows = cfg.bars.map(b => {
      const lines = wrapLabel(b.label, cfg.wrapChars);
      const neededH = Math.max(baseRowH, lines.length * lineH + 26);
      return { b, lines, rowH: neededH };
    });
    let cumY = M.top;
    rows.forEach(r => { r.y0 = cumY; cumY += r.rowH; });
    const H = cumY + M.bottom;

    const svg = makeSvg(W, H);
    addDefs(svg);

    // gridline + reference line
    if (cfg.refLine !== undefined) {
      const rx = M.left + xScale(cfg.refLine);
      svg.appendChild(el("line", { x1: rx, x2: rx, y1: M.top - 4, y2: H - M.bottom + 4, stroke: "rgba(255,255,255,.35)", "stroke-dasharray": "5,4" }));
      svg.appendChild(el("text", { x: rx, y: M.top - 8, fill: NAVY_TEXT, "font-size": 10, "text-anchor": "middle" }, cfg.refLineLabel || ""));
    }

    rows.forEach((r, i) => {
      const { b, lines, rowH, y0 } = r;
      const rowCy = y0 + rowH / 2;
      const barH = Math.min(cfg.barHeight || 26, rowH * 0.5);
      const barY = rowCy - barH / 2;
      const w = xScale(b.value);

      if (b.avatar) {
        const avR = Math.min(rowH * 0.32, 17);
        const avCx = avR + 6;
        const patId = `wtavatar-${idp}-${i}`;
        const pattern = el("pattern", { id: patId, patternUnits: "objectBoundingBox", width: 1, height: 1 });
        pattern.appendChild(el("image", { href: b.avatar, x: 0, y: 0, width: avR * 2, height: avR * 2, preserveAspectRatio: "xMidYMid slice" }));
        svg.querySelector("defs").appendChild(pattern);
        svg.appendChild(el("circle", { cx: avCx, cy: rowCy, r: avR, fill: `url(#${patId})`, stroke: "rgba(255,255,255,.5)", "stroke-width": 1.4 }));
      }

      const totalTextH = (lines.length - 1) * lineH;
      const startY = rowCy - totalTextH / 2 + 4;
      lines.forEach((ln, li) => {
        svg.appendChild(el("text", { x: M.left - 12, y: startY + li * lineH, fill: "#fff", "font-size": 12.5, "font-weight": 700, "text-anchor": "end" }, ln));
      });

      const grad = el("linearGradient", { id: `wtbar-${idp}-${i}`, x1: "0%", x2: "100%" });
      grad.innerHTML = `<stop offset="0%" stop-color="${b.color}" stop-opacity=".55"/><stop offset="100%" stop-color="${b.color}" stop-opacity=".95"/>`;
      svg.querySelector("defs").appendChild(grad);
      svg.appendChild(el("rect", { x: M.left, y: barY, width: Math.max(w, 2), height: barH, rx: barH / 2, fill: `url(#wtbar-${idp}-${i})`, filter: "url(#wt-shadow)" }));
      svg.appendChild(el("text", { x: M.left + w + 12, y: rowCy + 5, fill: "#fff", "font-size": 13.5, "font-weight": 700 }, b.valueLabel || (b.value + "%")));
    });

    svg.appendChild(el("line", { x1: M.left, x2: M.left, y1: M.top, y2: H - M.bottom, stroke: "rgba(255,255,255,.18)" }));
    svg.appendChild(el("text", { x: M.left + plotW / 2, y: H - 10, fill: NAVY_TEXT, "font-size": 12, "text-anchor": "middle" }, cfg.xLabel || ""));

    hostEl.appendChild(svg);
  }

  // ---------------- Concentric rings ----------------
  function concentric(hostEl, cfg) {
    const idp = cfg.idPrefix || Math.random().toString(36).slice(2, 8);
    const W = cfg.width || 640, H = cfg.height || 440;
    const cx = W / 2, cy = H / 2 + 10;
    const svg = makeSvg(W, H);
    addDefs(svg);

    const rings = cfg.rings; // outer to inner order in array, largest first
    rings.forEach((r, i) => {
      const grad = el("radialGradient", { id: `wtring-${idp}-${i}`, cx: "50%", cy: "45%", r: "60%" });
      grad.innerHTML = `<stop offset="0%" stop-color="${r.color}" stop-opacity=".18"/><stop offset="80%" stop-color="${r.color}" stop-opacity=".38"/><stop offset="100%" stop-color="${r.color}" stop-opacity=".08"/>`;
      svg.querySelector("defs").appendChild(grad);
      svg.appendChild(el("circle", { cx, cy, r: r.radius, fill: `url(#wtring-${idp}-${i})`, stroke: r.color, "stroke-width": 1.6, "stroke-opacity": .8 }));
    });

    // labels: each ring gets its own vertical band above center, so an outer
    // ring's text never collides with the rings nested inside it.
    const n = rings.length;
    rings.forEach((r, i) => {
      const innerR = (i + 1 < n) ? rings[i + 1].radius : 0;
      const outerR = r.radius;
      const isInnermost = i === n - 1;
      const tx = cx;
      // vertical center of this ring's label block: the middle of its annulus band,
      // or dead-center for the innermost filled circle.
      const bandCenterY = isInnermost ? cy : cy - (innerR + outerR) / 2;
      const lineGap = isInnermost ? 18 : 15;
      const fsName = isInnermost ? 15 : 13.5;
      const fsBody = isInnermost ? 11.5 : 10.5;
      const fsTotal = isInnermost ? 16 : 14;
      const ty = bandCenterY - lineGap * 1.1;
      const g = el("g", {});
      g.appendChild(el("text", { x: tx, y: ty, fill: "#fff", "font-size": fsName, "font-weight": 700, "text-anchor": "middle" }, r.name));
      g.appendChild(el("text", { x: tx, y: ty + lineGap, fill: NAVY_TEXT, "font-size": fsBody, "text-anchor": "middle" }, r.people));
      g.appendChild(el("text", { x: tx, y: ty + lineGap * 2, fill: NAVY_TEXT, "font-size": fsBody - .5, "font-style": "italic", "text-anchor": "middle" }, r.spend));
      g.appendChild(el("text", { x: tx, y: ty + lineGap * 3.1, fill: r.highlight ? "#EFC46D" : "#fff", "font-size": fsTotal, "font-weight": 700, "text-anchor": "middle" }, r.total));
      svg.appendChild(g);
    });

    hostEl.appendChild(svg);
  }

  // ---------------- Dot/line comparison (two methods) ----------------
  function dotline(hostEl, cfg) {
    const W = cfg.width || 760, H = cfg.height || 300;
    const M = { top: 40, right: 40, bottom: 46, left: 220 };
    const plotW = W - M.left - M.right;
    const xScale = v => M.left + (v / cfg.xMax) * plotW;
    const svg = makeSvg(W, H);
    addDefs(svg);

    // convergence band
    if (cfg.band) {
      const x1 = xScale(cfg.band.min), x2 = xScale(cfg.band.max);
      svg.appendChild(el("rect", { x: x1, y: 18, width: x2 - x1, height: H - 60, fill: "#EFC46D", opacity: .12 }));
      svg.appendChild(el("text", { x: (x1 + x2) / 2, y: 14, fill: "#EFC46D", "font-size": 11, "font-style": "italic", "text-anchor": "middle" }, cfg.band.label || ""));
    }

    const rowH = (H - 70) / cfg.rows.length;
    cfg.rows.forEach((r, i) => {
      const y = 50 + rowH * i + rowH / 2;
      svg.appendChild(el("text", { x: M.left - 16, y: y - 6, fill: "#fff", "font-size": 13, "font-weight": 700, "text-anchor": "end" }, r.label));
      svg.appendChild(el("text", { x: M.left - 16, y: y + 10, fill: NAVY_TEXT, "font-size": 10.5, "text-anchor": "end" }, r.sub || ""));

      const xa = xScale(r.min), xb = xScale(r.max);
      svg.appendChild(el("line", { x1: xa, x2: xb, y1: y, y2: y, stroke: "rgba(255,255,255,.5)", "stroke-width": 1.6 }));
      svg.appendChild(el("circle", { cx: xa, cy: y, r: 6, fill: "#0f2148", stroke: "#fff", "stroke-width": 2 }));
      svg.appendChild(el("circle", { cx: xb, cy: y, r: 6, fill: "#0f2148", stroke: "#fff", "stroke-width": 2 }));
      svg.appendChild(el("text", { x: xa, y: y - 14, fill: "#fff", "font-size": 12, "font-weight": 700, "text-anchor": "middle" }, r.minLabel));
      svg.appendChild(el("text", { x: xb, y: y - 14, fill: "#fff", "font-size": 12, "font-weight": 700, "text-anchor": "middle" }, r.maxLabel));

      if (r.mid !== undefined) {
        const xm = xScale(r.mid);
        svg.appendChild(el("rect", { x: xm - 7, y: y - 7, width: 14, height: 14, fill: "#EFC46D", transform: `rotate(45 ${xm} ${y})`, filter: "url(#wt-glow)" }));
        svg.appendChild(el("text", { x: xm, y: y + 26, fill: "#EFC46D", "font-size": 11, "font-weight": 700, "text-anchor": "middle" }, r.midLabel));
      }
    });

    // axis
    const axisY = H - 30;
    svg.appendChild(el("line", { x1: M.left, x2: W - M.right, y1: axisY, y2: axisY, stroke: "rgba(255,255,255,.2)" }));
    (cfg.xTicks || []).forEach(t => {
      const x = xScale(t);
      svg.appendChild(el("text", { x, y: axisY + 16, fill: NAVY_TEXT, "font-size": 10.5, "text-anchor": "middle" }, String(t)));
    });
    svg.appendChild(el("text", { x: M.left + plotW / 2, y: H - 4, fill: NAVY_TEXT, "font-size": 11.5, "text-anchor": "middle" }, cfg.xLabel || ""));

    hostEl.appendChild(svg);
  }

  // ---------------- Heatmap grid ----------------
  function heatmap(hostEl, cfg) {
    const labelW = cfg.labelWidth || 190, cellW = cfg.cellWidth || 110, cellH = cfg.cellHeight || 78, gap = 6;
    const W = labelW + cellW * cfg.columns.length + gap * cfg.columns.length;
    const H = 8 + (cellH + gap) * cfg.rows.length + 34;
    const svg = makeSvg(W, H);
    addDefs(svg);

    function colorFor(v) {
      if (v === null) return "#1a2745";
      const t = Math.max(0, Math.min(1, (v - cfg.min) / (cfg.max - cfg.min)));
      // interpolate navy -> gold -> red
      const stops = [
        { t: 0, c: [61, 88, 140] },
        { t: 0.5, c: [239, 196, 77] },
        { t: 1, c: [214, 69, 49] },
      ];
      let a = stops[0], b = stops[1];
      for (let i = 0; i < stops.length - 1; i++) if (t >= stops[i].t) { a = stops[i]; b = stops[i + 1]; }
      const localT = (t - a.t) / (b.t - a.t || 1);
      const c = a.c.map((v0, i) => Math.round(v0 + (b.c[i] - v0) * localT));
      return `rgb(${c[0]},${c[1]},${c[2]})`;
    }

    cfg.rows.forEach((row, ri) => {
      const y = 8 + ri * (cellH + gap);
      const fo = el("foreignObject", { x: 0, y, width: labelW - 10, height: cellH });
      fo.innerHTML = `<div xmlns="http://www.w3.org/1999/xhtml" style="color:#fff;font-size:12.5px;line-height:1.3;font-family:'Public Sans',sans-serif;display:flex;align-items:center;height:${cellH}px;border-left:3px solid #5B8CE0;padding-left:10px;">${row.label}</div>`;
      svg.appendChild(fo);

      row.values.forEach((v, ci) => {
        const x = labelW + ci * (cellW + gap);
        svg.appendChild(el("rect", { x, y, width: cellW, height: cellH, rx: 8, fill: colorFor(v) }));
        svg.appendChild(el("text", {
          x: x + cellW / 2, y: y + cellH / 2 + 6, fill: v === null ? "#5B7FC7" : "#1B2A4A",
          "font-size": 18, "font-weight": 700, "text-anchor": "middle"
        }, v === null ? "—" : v + "%"));
      });
    });

    cfg.columns.forEach((c, ci) => {
      const x = labelW + ci * (cellW + gap) + cellW / 2;
      svg.appendChild(el("text", { x, y: H - 12, fill: "#fff", "font-size": 12, "font-weight": 700, "text-anchor": "middle" }, c));
    });

    hostEl.appendChild(svg);
  }

  // ---------------- Age bar + gender donut combo ----------------
  function demoSplit(hostEl, cfg) {
    const W = cfg.width || 760, H = cfg.height || 360;
    const svg = makeSvg(W, H);
    addDefs(svg);

    const leftW = W * 0.52;
    svg.appendChild(el("text", { x: leftW / 2, y: 26, fill: "#fff", "font-size": 16, "font-weight": 700, "text-anchor": "middle" }, cfg.ageTitle || "Age"));
    const barsTop = 46, rowH = (H - barsTop - 20) / cfg.age.length;
    const maxV = Math.max(...cfg.age.map(a => a.value));
    const barMaxW = leftW - 130;
    cfg.age.forEach((a, i) => {
      const y = barsTop + i * rowH + rowH * 0.22;
      const barH = rowH * 0.5;
      const w = (a.value / maxV) * barMaxW;
      svg.appendChild(el("text", { x: 60, y: y + barH / 2 + 4, fill: "#fff", "font-size": 12.5, "font-weight": 700, "text-anchor": "end" }, a.label));
      svg.appendChild(el("rect", { x: 70, y, width: Math.max(w, 3), height: barH, rx: barH / 2, fill: "#5B8CE0", filter: "url(#wt-shadow)" }));
      svg.appendChild(el("text", { x: 70 + w + 10, y: y + barH / 2 + 4, fill: "#fff", "font-size": 12.5, "font-weight": 700 }, a.value + "%"));
    });

    // donut
    const cx = leftW + (W - leftW) / 2, cy = H / 2 + 6, r = Math.min(H, W - leftW) * 0.34;
    svg.appendChild(el("text", { x: cx, y: 26, fill: "#fff", "font-size": 16, "font-weight": 700, "text-anchor": "middle" }, cfg.genderTitle || "Gender"));
    svg.appendChild(el("line", { x1: leftW, x2: leftW, y1: 10, y2: H - 10, stroke: "rgba(255,255,255,.12)" }));

    let angle = -90;
    cfg.gender.forEach(g => {
      const sweep = (g.value / 100) * 360;
      const a0 = angle * Math.PI / 180, a1 = (angle + sweep) * Math.PI / 180;
      const x0 = cx + r * Math.cos(a0), y0 = cy + r * Math.sin(a0);
      const x1 = cx + r * Math.cos(a1), y1 = cy + r * Math.sin(a1);
      const largeArc = sweep > 180 ? 1 : 0;
      const path = `M${cx},${cy} L${x0},${y0} A${r},${r} 0 ${largeArc} 1 ${x1},${y1} Z`;
      svg.appendChild(el("path", { d: path, fill: g.color, "fill-opacity": .9, stroke: "#12192A", "stroke-width": 2 }));

      const midA = (angle + sweep / 2) * Math.PI / 180;
      const lx = cx + r * 0.62 * Math.cos(midA), ly = cy + r * 0.62 * Math.sin(midA);
      svg.appendChild(el("text", { x: lx, y: ly + 5, fill: "#1B2A4A", "font-size": 15, "font-weight": 700, "text-anchor": "middle" }, g.value + "%"));

      const llx = cx + r * 1.18 * Math.cos(midA), lly = cy + r * 1.18 * Math.sin(midA);
      svg.appendChild(el("text", { x: llx, y: lly, fill: "#fff", "font-size": 12, "text-anchor": midA > -Math.PI/2 && midA < Math.PI/2 ? "start" : "end" }, g.label));
      angle += sweep;
    });

    hostEl.appendChild(svg);
  }

  return { bubble, hbar, concentric, dotline, heatmap, demoSplit };
})();
window.WTReportUI = function () {

(function(){
  // toggle: two-way / three-way
  document.querySelectorAll('.toggle-btn').forEach(function(btn){
    btn.addEventListener('click', function(){
      var scope = btn.closest('section');
      scope.querySelectorAll('.toggle-btn').forEach(function(b){b.classList.remove('active');});
      scope.querySelectorAll('.toggle-panel').forEach(function(p){p.classList.remove('active');});
      btn.classList.add('active');
      var target = document.getElementById(btn.getAttribute('data-target'));
      if(target) target.classList.add('active');
    });
  });

  // persona tabs
  document.querySelectorAll('.ptab').forEach(function(btn){
    btn.addEventListener('click', function(){
      var p = btn.getAttribute('data-p');
      document.querySelectorAll('.ptab').forEach(function(b){b.classList.remove('active');});
      document.querySelectorAll('.persona-panel').forEach(function(pan){pan.classList.remove('active');});
      btn.classList.add('active');
      var panel = document.querySelector('.persona-panel[data-p="'+p+'"]');
      if(panel) panel.classList.add('active');
    });
  });

  // mobile nav drawer toggle
  try{
    var navEl = document.querySelector('nav.top');
    var toggleBtn = document.getElementById('navToggle');
    var navLinksEl = document.getElementById('navLinks');
    if(toggleBtn && navEl){
      toggleBtn.addEventListener('click', function(){
        var isOpen = navEl.classList.toggle('open');
        toggleBtn.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
      });
      navLinksEl.querySelectorAll('a').forEach(function(a){
        a.addEventListener('click', function(){
          navEl.classList.remove('open');
          toggleBtn.setAttribute('aria-expanded', 'false');
        });
      });
    }
  }catch(e){}

  // right-edge fade when the nav-links row can scroll further
  try{
    var navElFade = document.querySelector('nav.top');
    var scroller = document.getElementById('navLinks');
    function updateFade(){
      if(!scroller || !navElFade) return;
      var canScroll = scroller.scrollWidth - scroller.clientWidth - scroller.scrollLeft > 4;
      navElFade.classList.toggle('can-scroll', canScroll);
    }
    if(scroller){
      updateFade();
      scroller.addEventListener('scroll', updateFade);
      window.addEventListener('resize', updateFade);
    }
  }catch(e){}

  // active nav link on scroll
  try{
    var links = Array.from(document.querySelectorAll('nav.top a'));
    var sections = links.map(function(l){ return document.querySelector(l.getAttribute('href')); }).filter(Boolean);
    var navScroller = document.getElementById('navLinks');
    var io = new IntersectionObserver(function(entries){
      entries.forEach(function(entry){
        if(entry.isIntersecting){
          var id = '#' + entry.target.id;
          links.forEach(function(l){ l.classList.toggle('active', l.getAttribute('href') === id); });
          var activeLink = links.find(function(l){ return l.getAttribute('href') === id; });
          if(activeLink && navScroller){
            var linkLeft = activeLink.offsetLeft;
            var linkRight = linkLeft + activeLink.offsetWidth;
            var viewLeft = navScroller.scrollLeft;
            var viewRight = viewLeft + navScroller.clientWidth;
            if(linkLeft < viewLeft || linkRight > viewRight){
              activeLink.scrollIntoView({inline:'center', block:'nearest', behavior:'smooth'});
            }
          }
        }
      });
    }, {rootMargin: '-40% 0px -55% 0px'});
    sections.forEach(function(s){ io.observe(s); });
  }catch(e){}
})();

};